        .hero-subtitle {
            font-family: var(--font-heading);
            font-size: 1rem;
            letter-spacing: 8px;
            text-transform: uppercase;
            color: var(--aged-gold);
            margin-bottom: 2rem;
            animation: fadeInUp 1s ease 0.5s both;
        }

        .hero-title {
            font-family: var(--font-title);
            font-size: clamp(3rem, 8vw, 6rem);
            line-height: 1.1;
            margin-bottom: 2rem;
            color: var(--ivory);
            text-shadow: 0 0 40px rgba(201, 169, 97, 0.3);
            animation: fadeInUp 1s ease 0.7s both;
        }

        .hero-quote {
            font-family: var(--font-mono);
            font-style: italic;
            font-size: clamp(1.2rem, 3vw, 1.8rem);
            color: var(--ivory);
            opacity: 0.9;
            margin-bottom: 3rem;
            padding: 2rem;
            border-left: 3px solid var(--aged-gold);
            border-right: 3px solid var(--aged-gold);
            animation: fadeInUp 1s ease 0.9s both;
        }

        .hero-buttons {
            display: flex;
            gap: 1.5rem;
            justify-content: center;
            flex-wrap: wrap;
            animation: fadeInUp 1s ease 1.1s both;
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .scroll-indicator {
            position: absolute;
            bottom: 3rem;
            left: 50%;
            transform: translateX(-50%);
            animation: bounce 2s ease-in-out infinite;
        }

        .scroll-indicator i {
            color: var(--aged-gold);
            font-size: 1.5rem;
        }

        @keyframes bounce {
            0%, 100% { transform: translateX(-50%) translateY(0); }
            50% { transform: translateX(-50%) translateY(10px); }
        }

        /* Section Styles */
        section {
            padding: 6rem 2rem;
            max-width: 1400px;
            margin: 0 auto;
        }

        .section-header {
            text-align: center;
            margin-bottom: 4rem;
        }

        .section-subtitle {
            font-family: var(--font-heading);
            font-size: 0.9rem;
            letter-spacing: 6px;
            text-transform: uppercase;
            color: var(--aged-gold);
            margin-bottom: 1rem;
