        .work-category {
            font-family: var(--font-heading);
            font-size: 0.7rem;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--aged-gold);
            margin-bottom: 0.5rem;
        }

        .work-title {
            font-family: var(--font-heading);
            font-size: 1.4rem;
            color: var(--ivory);
            margin-bottom: 0.75rem;
            line-height: 1.3;
        }

        .work-excerpt {
            font-family: var(--font-mono);
            font-size: 1rem;
            color: var(--ivory);
            opacity: 0.7;
            line-height: 1.8;
            margin-bottom: 1rem;
