        .work-author:hover {
            color: var(--ivory);
        }

        .work-stats {
            display: flex;
            gap: 1rem;
            color: var(--ivory);
            opacity: 0.6;
        }

        .work-stats span {
            display: flex;
            align-items: center;
            gap: 0.3rem;
        }

        /* Filter Bar */
        .filter-bar {
            display: flex;
            gap: 1rem;
            justify-content: center;
            flex-wrap: wrap;
            margin-bottom: 3rem;
        }

        .filter-btn {
            padding: 0.5rem 1.5rem;
            border: 1px solid rgba(201, 169, 97, 0.3);
            background: transparent;
            color: var(--ivory);
            font-family: var(--font-heading);
            font-size: 0.8rem;
            letter-spacing: 1px;
            text-transform: uppercase;
