        }

        .search-input {
            width: 100%;
            padding: 1rem 3rem 1rem 1.5rem;
            background: var(--charcoal);
            border: 1px solid rgba(201, 169, 97, 0.3);
            border-radius: 50px;
            color: var(--ivory);
            font-family: var(--font-body);
            font-size: 1rem;
            transition: all 0.3s ease;
        }

        .search-input:focus {
            outline: none;
            border-color: var(--aged-gold);
            box-shadow: 0 0 20px rgba(201, 169, 97, 0.2);
        }

        .search-icon {
            position: absolute;
            right: 1.5rem;
            top: 50%;
            transform: translateY(-50%);
            color: var(--aged-gold);
        }

        /* Authors Section */
        .authors-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 2rem;
        }

        .author-card {
            text-align: center;
            padding: 2rem;
            background: var(--charcoal);
            border: 1px solid rgba(201, 169, 97, 0.2);
            border-radius: 4px;
            transition: all 0.4s ease;
        }

        .author-card:hover {
            border-color: var(--aged-gold);
            transform: translateY(-5px);
        }

        .author-avatar {
            width: 120px;
            height: 120px;
            border-radius: 50%;
            object-fit: cover;
            border: 3px solid var(--aged-gold);
            margin: 0 auto 1.5rem;
            padding: 5px;
            background: var(--charcoal);
