        .author-name {
            font-family: var(--font-heading);
            font-size: 1.3rem;
            color: var(--ivory);
            margin-bottom: 0.5rem;
        }

        .author-genre {
            font-family: var(--font-body);
            font-style: italic;
            color: var(--aged-gold);
            font-size: 0.9rem;
            margin-bottom: 1rem;
        }

        .author-bio {
            font-family: var(--font-mono);
            font-size: 0.95rem;
            color: var(--ivory);
            opacity: 0.7;
            line-height: 1.8;
            margin-bottom: 1.5rem;
        }

        .author-stats {
            display: flex;
            justify-content: center;
            gap: 2rem;
            padding-top: 1.5rem;
            border-top: 1px solid rgba(201, 169, 97, 0.2);
        }

        .stat {
            text-align: center;
        }

        .stat-value {
            font-family: var(--font-heading);
            font-size: 1.5rem;
            color: var(--aged-gold);
        }

        .stat-label {
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--ivory);
            opacity: 0.6;
        }

        /* Magazine Section */
        .magazine-featured {
            background: var(--charcoal);
            border: 1px solid rgba(201, 169, 97, 0.3);
