            flex-direction: column;
            justify-content: center;
        }

        .magazine-label {
            font-family: var(--font-heading);
            font-size: 0.8rem;
            letter-spacing: 4px;
            text-transform: uppercase;
            color: var(--blood-red);
            margin-bottom: 1rem;
        }

        .magazine-title {
            font-family: var(--font-title);
            font-size: 2.5rem;
            color: var(--ivory);
            margin-bottom: 1.5rem;
            line-height: 1.2;
        }

        .magazine-excerpt {
            font-family: var(--font-mono);
            font-size: 1.1rem;
            color: var(--ivory);
            opacity: 0.8;
            line-height: 1.9;
            margin-bottom: 2rem;
        }

        .contests-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .contest-card {
            background: linear-gradient(135deg, var(--charcoal) 0%, var(--stone-gray) 100%);
            border: 1px solid rgba(201, 169, 97, 0.2);
            border-radius: 8px;
            padding: 2rem;
            transition: all 0.4s ease;
            position: relative;
            overflow: hidden;
        }

        .contest-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 4px;
            background: linear-gradient(90deg, var(--dark-red), var(--aged-gold));
        }

        .contest-card:hover {
            transform: translateY(-5px);
            border-color: var(--aged-gold);
        }

        .contest-deadline {
            font-family: var(--font-heading);
            font-size: 0.75rem;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: var(--blood-red);
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .contest-title {
            font-family: var(--font-heading);
            font-size: 1.4rem;
            color: var(--ivory);
            margin-bottom: 1rem;
        }

        .contest-prize {
            font-family: var(--font-mono);
            font-size: 1rem;
            color: var(--aged-gold);
            margin-bottom: 1.5rem;
        }

        /* Editor Section */
        .editor-section {
            background: var(--charcoal);
            border: 1px solid rgba(201, 169, 97, 0.2);
            border-radius: 8px;
            padding: 3rem;
            margin-top: 3rem;
