        .editor-header {
            display: flex;
            align-items: center;
            gap: 2rem;
            margin-bottom: 2rem;
            padding-bottom: 2rem;
            border-bottom: 1px solid rgba(201, 169, 97, 0.2);
        }

        .editor-avatar {
            width: 80px;
            height: 80px;
            border-radius: 50%;
            object-fit: cover;
            border: 2px solid var(--aged-gold);
        }

        .editor-info h3 {
            font-family: var(--font-heading);
            font-size: 1.5rem;
            color: var(--ivory);
            margin-bottom: 0.5rem;
        }

        .editor-info p {
            font-family: var(--font-body);
            font-style: italic;
            color: var(--aged-gold);
        }

        .editor-note {
            font-family: var(--font-mono);
            font-size: 1.1rem;
            color: var(--ivory);
            opacity: 0.9;
            line-height: 2;
            padding-left: 2rem;
            border-left: 3px solid var(--aged-gold);
        }

        /* Write Section */
        .write-section {
            background: var(--charcoal);
            border: 1px solid rgba(201, 169, 97, 0.3);
            border-radius: 8px;
            padding: 3rem;
            max-width: 900px;
            margin: 0 auto;
        }

        .editor-container {
            margin-top: 2rem;
        }

        .editor-toolbar {
            display: flex;
            gap: 0.5rem;
            padding: 1rem;
            background: var(--stone-gray);
            border-radius: 8px 8px 0 0;
            border: 1px solid rgba(201, 169, 97, 0.2);
            border-bottom: none;
            flex-wrap: wrap;
        }

        .toolbar-btn {
            padding: 0.5rem 0.75rem;
            background: transparent;
            border: none;
            color: var(--ivory);
            cursor: pointer;
            border-radius: 4px;
            transition: all 0.3s ease;
        }

        .toolbar-btn:hover {
            background: var(--aged-gold);
            color: var(--black);
        }

        .editor-textarea {
            width: 100%;
            min-height: 400px;
            padding: 1.5rem;
            background: var(--black);
            border: 1px solid rgba(201, 169, 97, 0.2);
            border-radius: 0 0 8px 8px;
            color: var(--ivory);
            font-family: var(--font-mono);
            font-size: 1.1rem;
            line-height: 2;
            resize: vertical;
        }

        .editor-textarea:focus {
            outline: none;
            border-color: var(--aged-gold);
        }

        .form-group {
            margin-bottom: 1.5rem;
        }

        .form-label {
            display: block;
            font-family: var(--font-heading);
            font-size: 0.85rem;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: var(--aged-gold);
            margin-bottom: 0.5rem;
        }

        .form-input,
        .form-select {
            width: 100%;
            padding: 1rem;
            background: var(--black);
            border: 1px solid rgba(201, 169, 97, 0.3);
            border-radius: 4px;
            color: var(--ivory);
            font-family: var(--font-body);
            font-size: 1rem;
            transition: all 0.3s ease;
        }

        .form-input:focus,
        .form-select:focus {
            outline: none;
            border-color: var(--aged-gold);
        }

        .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1.5rem;
