        .footer-section a:hover {
            opacity: 1;
            color: var(--aged-gold);
        }

        .social-links {
            display: flex;
            gap: 1rem;
            margin-top: 1rem;
        }

        .social-link {
            width: 45px;
            height: 45px;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 1px solid rgba(201, 169, 97, 0.3);
            border-radius: 50%;
            color: var(--aged-gold);
            transition: all 0.3s ease;
        }

        .social-link:hover {
            background: var(--aged-gold);
            color: var(--black);
            border-color: var(--aged-gold);
        }

        .footer-bottom {
            max-width: 1400px;
            margin: 3rem auto 0;
            padding-top: 2rem;
            border-top: 1px solid rgba(201, 169, 97, 0.2);
            text-align: center;
            font-family: var(--font-mono);
            font-size: 0.85rem;
            color: var(--ivory);
            opacity: 0.5;
        }

        /* Modal */
        .modal {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.9);
            z-index: 2000;
            justify-content: center;
            align-items: center;
            padding: 2rem;
        }

        .modal.active {
            display: flex;
        }

        .modal-content {
            background: var(--charcoal);
            border: 1px solid rgba(201, 169, 97, 0.3);
            border-radius: 8px;
            max-width: 800px;
            width: 100%;
            max-height: 90vh;
            overflow-y: auto;
            position: relative;
        }

        .modal-close {
            position: absolute;
            top: 1rem;
            right: 1rem;
            background: none;
            border: none;
            color: var(--ivory);
            font-size: 1.5rem;
            cursor: pointer;
            z-index: 10;
            transition: all 0.3s ease;
        }

        .modal-close:hover {
            color: var(--aged-gold);
            transform: rotate(90deg);
        }

        .modal-body {
            padding: 3rem;
        }

        /* Responsive */
        @media (max-width: 992px) {
            .magazine-featured {
                grid-template-columns: 1fr;
            }

            .magazine-image {
                min-height: 300px;
            }

            .editor-header {
                flex-direction: column;
                text-align: center;
            }
        }

        @media (max-width: 768px) {
            nav {
                padding: 1rem 1.5rem;
            }

            .nav-links {
                display: none;
                position: absolute;
                top: 100%;
                left: 0;
                width: 100%;
                background: var(--charcoal);
                flex-direction: column;
                padding: 2rem;
                gap: 1.5rem;
                border-bottom: 1px solid rgba(201, 169, 97, 0.2);
            }

            .nav-links.active {
                display: flex;
            }

            .mobile-menu {
                display: flex;
            }

            .hero {
                padding: 6rem 1.5rem 3rem;
            }

            .form-row {
                grid-template-columns: 1fr;
            }

            .library-grid,
            .authors-grid,
            .contests-grid {
                grid-template-columns: 1fr;
            }

            section {
                padding: 4rem 1.5rem;
            }
        }

        /* Scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
        }

        ::-webkit-scrollbar-track {
            background: var(--black);
        }

        ::-webkit-scrollbar-thumb {
            background: var(--aged-gold);
            border-radius: 4px;
        }

        ::-webkit-scrollbar-thumb:hover {
            background: var(--blood-red);
        }

        /* Animations */
        .fade-in {
            opacity: 0;
            transform: translateY(30px);
            transition: all 0.6s ease;
        }

        .fade-in.visible {
            opacity: 1;
            transform: translateY(0);
        }
    </style>
</head>
